FString IKRigUtils::DiscoverSolvers(const FString& Search,int32 Limit)
{
 if(!IsInGameThread() || Search.Len()>128 || Limit<1 || Limit>128) throw std::runtime_error("Solver discovery requires bounded search/limit"); TArray<UScriptStruct*> Types;
 for(TObjectIterator<UScriptStruct> It;It;++It) if(*It!=FIKRigSolverBase::StaticStruct() && It->IsChildOf(FIKRigSolverBase::StaticStruct()) && It->GetOutermost()->GetName().StartsWith(TEXT("/Script/")) && (Search.IsEmpty() || It->GetPathName().Contains(Search))) Types.Add(*It);
 Types.Sort([](const UScriptStruct& A,const UScriptStruct& B) { return A.GetPathName()<B.GetPathName(); });
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("match_count"),Types.Num()); J->WriteValue(TEXT("truncated"),Types.Num()>Limit); J->WriteArrayStart(TEXT("solvers"));
 for(int32 Index=0;Index<FMath::Min(Types.Num(),Limit);++Index)
 {
  auto* Type=Types[Index]; FStructOnScope Defaults(Type); /* Tunable values live in the separate native settings struct, not on the FIKRigSolverBase struct itself. */ auto* Native=reinterpret_cast<FIKRigSolverBase*>(Defaults.GetStructMemory()); const UScriptStruct* FieldsType=Native->GetSolverSettingsType(); void* FieldsMemory=FieldsType ? static_cast<void*>(Native->GetSolverSettings()) : nullptr; if(!FieldsType || !FieldsMemory) { FieldsType=Type; FieldsMemory=Defaults.GetStructMemory(); } J->WriteObjectStart(); J->WriteValue(TEXT("struct_path"),Type->GetPathName()); J->WriteValue(TEXT("display_name"),Type->GetDisplayNameText().ToString()); J->WriteArrayStart(TEXT("editable_fields")); int32 Fields=0;
  for(TFieldIterator<FProperty> It(FieldsType);It;++It) if(It->HasAnyPropertyFlags(CPF_Edit) && !It->HasAnyPropertyFlags(CPF_Transient|CPF_Deprecated)) { if(Fields++>=64) continue; FString Value; It->ExportTextItem_Direct(Value,It->ContainerPtrToValuePtr<void>(FieldsMemory),nullptr,nullptr,PPF_None); J->WriteObjectStart(); J->WriteValue(TEXT("name"),It->GetName()); J->WriteValue(TEXT("type"),It->GetCPPType()); { const UEnum* Enum=nullptr; if(const auto* EnumField=CastField<FEnumProperty>(*It)) Enum=EnumField->GetEnum(); else if(const auto* Byte=CastField<FByteProperty>(*It)) Enum=Byte->Enum; if(Enum) { J->WriteValue(TEXT("enum_path"),Enum->GetPathName()); J->WriteValue(TEXT("enum_choices_truncated"),Enum->NumEnums()>128); J->WriteArrayStart(TEXT("enum_choices")); for(int32 Choice=0;Choice<FMath::Min(Enum->NumEnums(),128);++Choice) { const FString ChoiceName=Enum->GetNameStringByIndex(Choice); const bool Hidden=Enum->HasMetaData(TEXT("Hidden"),Choice),Sentinel=ChoiceName.EndsWith(TEXT("_MAX")); J->WriteObjectStart(); J->WriteValue(TEXT("name"),ChoiceName); J->WriteValue(TEXT("value"),Enum->GetValueByIndex(Choice)); J->WriteValue(TEXT("editable"),!Hidden && !Sentinel); J->WriteObjectEnd(); } J->WriteArrayEnd(); } } J->WriteValue(TEXT("edit_const"),It->HasAnyPropertyFlags(CPF_EditConst)); J->WriteValue(TEXT("default"),Value.Left(2048)); J->WriteValue(TEXT("value_truncated"),Value.Len()>2048); for(const FName Key:{FName(TEXT("ClampMin")),FName(TEXT("ClampMax"))}) if(It->HasMetaData(Key)) J->WriteValue(Key.ToString(),It->GetMetaData(Key)); J->WriteObjectEnd(); }
  J->WriteArrayEnd(); J->WriteValue(TEXT("field_count"),Fields); J->WriteValue(TEXT("fields_truncated"),Fields>64); J->WriteObjectEnd();
 }
 J->WriteArrayEnd(); J->WriteValue(TEXT("scope"),TEXT("Loaded native derived solver struct discovery/defaults; native controller decides addability. Export text intermediate allocation follows native property exporter.")); J->WriteObjectEnd(); J->Close(); return Result;
}

