 if(!IsInGameThread() || R.AssetPath.Len()>1024 || R.AssetPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(R.AssetPath) || R.MeshPath.IsEmpty() || R.MeshPath.Len()>1024 || R.MeshPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(R.MeshPath)) throw std::runtime_error("Compatibility query requires bounded persistent rig and mesh object paths");
 auto& Registry=FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry")).Get(); if(!Registry.GetAssetByObjectPath(FSoftObjectPath(R.AssetPath)).IsValid() || !Registry.GetAssetByObjectPath(FSoftObjectPath(R.MeshPath)).IsValid()) throw std::runtime_error("Rig and skeletal mesh must exist in registry"); auto* Rig=LoadObject<UIKRigDefinition>(nullptr,*R.AssetPath); auto* Mesh=LoadObject<USkeletalMesh>(nullptr,*R.MeshPath); if(!IsValid(Rig) || Rig->HasAnyFlags(RF_Transient) || !IsValid(Mesh) || Mesh->HasAnyFlags(RF_Transient) || Mesh->GetRefSkeleton().GetNum()==0 || Mesh->GetRefSkeleton().GetNum()>4096) throw std::runtime_error("Persistent rig and skeletal mesh with 1..4096 bones required");
