 if(!R.bDryRun && Changed) { auto* Controller=UIKRigController::GetController(Asset); if(!Controller) throw std::runtime_error("Native controller unavailable"); auto* MutableSolver=Controller->GetSolverAtIndex(R.SolverIndex); if(!MutableSolver) throw std::runtime_error("Native solver unavailable"); FScopedTransaction Transaction(FText::FromString(TEXT("MCP Reset IK Solver Settings"))); Asset->Modify(); MutableSolver->SetSolverSettings(reinterpret_cast<const FIKRigSolverSettingsBase*>(Defaults.GetStructMemory())); Asset->PostEditChange(); Asset->MarkPackageDirty(); }
